diff --git a/lib/src/cli/agent_cli_budget.dart b/lib/src/cli/agent_cli_budget.dart
index 4e4d07773e..bbd3943293 100644
--- a/lib/src/cli/agent_cli_budget.dart
+++ b/lib/src/cli/agent_cli_budget.dart
@@ -14,10 +14,14 @@ extension AgentCliBudget on AgentCli {
     _outstandingBudgetOffer = toolCallId;
   }

-  /// The offer is gone: a terminal budget action fired (background /
-  /// abort), or the call ended, or the accept already consumed it.
-  void budgetOfferCleared() {
-    _outstandingBudgetOffer = null;
+  /// The offer is gone: a terminal budget action fired for [toolCallId]
+  /// (background / abort), or THAT call ended, or the accept already
+  /// consumed it. A different call's end never clears this offer (issue
+  /// #2272: parallel batches end their calls independently).
+  void budgetOfferCleared(String toolCallId) {
+    if (_outstandingBudgetOffer == toolCallId) {
+      _outstandingBudgetOffer = null;
+    }
   }

   /// Whether the stall banner should advertise the `b` affordance.
diff --git a/lib/src/cli/approval_commands.dart b/lib/src/cli/approval_commands.dart
index 1e83cfe4cd..2195a5fa7b 100644
--- a/lib/src/cli/approval_commands.dart
+++ b/lib/src/cli/approval_commands.dart
@@ -1287,7 +1287,7 @@ extension ApprovalCommands on AgentCli {
         if (action == ForegroundBudgetAction.offer) {
           budgetOfferSurfaced(toolCallId);
         } else {
-          budgetOfferCleared();
+          budgetOfferCleared(toolCallId);
         }
         // The terminal line carries the deterministic announcement (the
         // detail IS the `[foreground-budget] …` line) — redacted the same
@@ -1801,8 +1801,10 @@ extension ApprovalCommands on AgentCli {
         _toolStarts.remove(toolCallId) ?? (null, '', const <String, dynamic>{});
     _waiting.toolCallEnded(toolCallId);
     // No offer may outlive its call (issue #1786): the call ending is the
-    // last chance to clear a stale outstanding `b` affordance.
-    budgetOfferCleared();
+    // last chance to clear a stale outstanding `b` affordance — but only
+    // the OFFERED call's end clears it (issue #2272: a parallel sibling
+    // ending must not wipe another call's live affordance).
+    budgetOfferCleared(toolCallId);
     final elapsed = started == null
         ? ''
         : '${DateTime.now().difference(started).inSeconds}s';
