library;

import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_steering_persistence_test.dart' show waitForSessions;
import 'agent_cli_test_support.dart';

class PerCallGatedShell implements Shell {
  PerCallGatedShell(this.gates);
  final Map<String, Completer<void>> gates;
  void release(String command) => gates[command]?.complete();

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    await gates[command]?.future;
    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
  }
}

void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;
  var now = DateTime.utc(2026, 1, 1, 12);

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work', shell: PerCallGatedShell({}));
    io = FakeCliIO();
    now = DateTime.utc(2026, 1, 1, 12);
  });
  tearDown(() => io.close());

  AgentCli cliFor(FakeStreamFunction fake, MemoryExecutionEnv localEnv) =>
      AgentCli(
        config: AgentCliConfig(
          model: testModel,
          apiKey: '[REDACTED:Sensitive-Value]',
          env: localEnv,
          sessionRoot: '/sessions',
          approvalMode: ApprovalMode.yolo,
          foregroundCall: const ForegroundCallBudgetConfig(
            budget: Duration(minutes: 10),
            cancelGrace: Duration(milliseconds: 120),
          ),
        ),
        io: io,
        streamFunction: fake.call,
        waitingClock: () => now,
      );

  test('P1: which call id holds the offer after the watchdog tick', () async {
    final gates = {
      'make release-a': Completer<void>(),
      'make release-b': Completer<void>(),
    };
    final localEnv = MemoryExecutionEnv(
      cwd: '/work',
      shell: PerCallGatedShell(gates),
    );
    final fake = FakeStreamFunction([
      toolTurn(const [
        ToolCall(
          id: 'ta',
          name: 'bash',
          arguments: {'command': 'make release-a'},
        ),
        ToolCall(
          id: 'tb',
          name: 'bash',
          arguments: {'command': 'make release-b'},
        ),
      ]),
      textTurn('steered reply'),
      textTurn('done'),
      textTurn('spare'),
    ]);
    final cli = cliFor(fake, localEnv);
    final run = cli.run();
    await waitForSessions(localEnv);
    io.sendLine('hi');
    await waitForIt(
      () => cli.toolLivenessCallsForTest.length == 2,
      reason: 'both parallel calls watched',
    );
    // ignore: avoid_print
    print('PROBE watched ids: '
        '${cli.toolLivenessCallsForTest.map((c) => c.id).toList()}');

    await cli.steerForTest('switch to plan b');
    now = now.add(const Duration(seconds: 300));
    cli.toolLivenessTickForTest();
    await waitForIt(() => cli.hasOutstandingBudgetOffer,
        reason: 'offer surfaced');
    // ignore: avoid_print
    print('PROBE after tick: offer=${cli.hasOutstandingBudgetOffer} '
        'watched=${cli.toolLivenessCallsForTest.map((c) => c.id).toList()}');

    gates['make release-a']!.complete();
    await waitForIt(
      () => cli.toolLivenessCallsForTest.length == 1,
      reason: 'first call ended',
    );
    // ignore: avoid_print
    print('PROBE after release-a: offer=${cli.hasOutstandingBudgetOffer} '
        'watched=${cli.toolLivenessCallsForTest.map((c) => c.id).toList()}');

    gates['make release-b']!.complete();
    await waitForIt(() => cli.toolLivenessCallsForTest.isEmpty,
        reason: 'second call ended');
    // ignore: avoid_print
    print('PROBE after release-b: offer=${cli.hasOutstandingBudgetOffer}');

    io.sendLine('/exit');
    await run;
    // ignore: avoid_print
    print('PROBE budget lines: '
        '${io.out.toString().split('\n').where((l) => l.contains('[foreground-budget]')).toList()}');
  });
}

